import { useState, useEffect, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import StatsCard from './components/StatsCard';
import ScreenDetector from './components/ScreenDetector';
import LiveMonitor from './components/LiveMonitor';
import AlertPanel from './components/AlertPanel';

// ─── Dummy seed alerts ────────────────────────────────────────
const SEED_ALERTS = [
  {
    id: 1,
    type: 'No Plate',
    severity: 'orange',
    description: 'Motor Honda Beat — plat nomor tidak ada',
    camera: 'CAM-01 · Gate A',
    time: '07:52:14',
    status: 'reviewing',
    isNew: false,
  },
  {
    id: 2,
    type: 'Suspicious Vehicle',
    severity: 'red',
    description: 'Mobil tidak dikenal berhenti >10 menit di zona terlarang',
    camera: 'CAM-03 · Parkir',
    time: '08:04:39',
    status: 'unreviewed',
    isNew: false,
  },
  {
    id: 3,
    type: 'Plate Obscured',
    severity: 'orange',
    description: 'Toyota Avanza — plat nomor tertutup stiker hitam',
    camera: 'CAM-02 · Gate B',
    time: '08:17:05',
    status: 'unreviewed',
    isNew: false,
  },
];

// ─── Alert generator templates ────────────────────────────────
const ALERT_POOL = [
  {
    type: 'No Plate',
    severity: 'orange',
    descriptions: [
      'Yamaha NMAX — tidak ada plat nomor depan maupun belakang',
      'Honda PCX — plat nomor dilepas, terdeteksi masuk gate',
      'Motor bebek tidak dikenal — tanpa plat nomor',
      'Vespa Sprint — plat nomor hilang, bergerak cepat',
    ],
    cameras: ['CAM-01 · Gate A', 'CAM-04 · Exit'],
  },
  {
    type: 'Plate Obscured',
    severity: 'orange',
    descriptions: [
      'Daihatsu Sigra — plat nomor tertutup lumpur tebal',
      'Mitsubishi Pajero — plat ditutupi lakban hitam',
      'Toyota Rush — plat nomor dilepas sementara di parkir',
      'Avanza putih — stiker menutupi sebagian nomor kendaraan',
    ],
    cameras: ['CAM-02 · Gate B', 'CAM-03 · Parkir'],
  },
  {
    type: 'Suspicious Vehicle',
    severity: 'red',
    descriptions: [
      'Kendaraan tidak dikenal berputar-putar berkali-kali di area dalam',
      'Minibus gelap parkir di zona larangan lebih dari 15 menit',
      'Mobil dengan kaca film sangat gelap, tidak bisa diidentifikasi penumpang',
      'Kendaraan bergerak mundur perlahan mendekati area terbatas',
    ],
    cameras: ['CAM-01 · Gate A', 'CAM-03 · Parkir', 'CAM-05 · Lobby'],
  },
  {
    type: 'Wrong Lane',
    severity: 'red',
    descriptions: [
      'Motor masuk jalur keluar (berlawanan arah)',
      'Truk kecil memasuki jalur penumpang — tidak sesuai izin',
    ],
    cameras: ['CAM-04 · Exit'],
  },
];

let _idCounter = 200;
const pad = n => String(n).padStart(2, '0');
const nowTime = () => {
  const d = new Date();
  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
};
const rand = arr => arr[Math.floor(Math.random() * arr.length)];

// ─── App ──────────────────────────────────────────────────────
export default function App() {
  // Detection state
  const [isRunning, setIsRunning]   = useState(false);
  const [stream, setStream]         = useState(null);

  // Alert state
  const [alerts, setAlerts]         = useState(SEED_ALERTS);

  // Stats state
  const [stats, setStats] = useState({
    totalToday:  52,
    normal:      48,
    noPlate:      3,
    suspicious:   1,
  });

  const simulationRef = useRef(null);

  // ── Start screen capture ──────────────────────────────────
  const handleStart = useCallback(async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getDisplayMedia({
        video: { cursor: 'always', frameRate: 30 },
        audio: false,
      });

      // Handle user closing via browser's native stop button
      mediaStream.getVideoTracks()[0].addEventListener('ended', () => {
        setIsRunning(false);
        setStream(null);
      });

      setStream(mediaStream);
      setIsRunning(true);
    } catch (err) {
      console.warn('Screen capture cancelled or denied:', err.message);
    }
  }, []);

  // ── Stop detection ────────────────────────────────────────
  const handleStop = useCallback(() => {
    if (stream) stream.getTracks().forEach(t => t.stop());
    setStream(null);
    setIsRunning(false);
  }, [stream]);

  // ── Alert simulation when running ────────────────────────
  useEffect(() => {
    if (!isRunning) {
      clearInterval(simulationRef.current);
      return;
    }

    // Interval varies between 5-10 seconds as specified
    const scheduleNext = () => {
      const delay = 5000 + Math.random() * 5000;
      simulationRef.current = setTimeout(() => {
        const tpl     = rand(ALERT_POOL);
        const newAlert = {
          id:          ++_idCounter,
          type:        tpl.type,
          severity:    tpl.severity,
          description: rand(tpl.descriptions),
          camera:      rand(tpl.cameras),
          time:        nowTime(),
          status:      'unreviewed',
          isNew:       true,
        };

        setAlerts(prev => [newAlert, ...prev].slice(0, 40));

        setStats(prev => {
          const isNP = tpl.type === 'No Plate' || tpl.type === 'Plate Obscured';
          const isSS = tpl.type === 'Suspicious Vehicle' || tpl.type === 'Wrong Lane';
          return {
            totalToday:  prev.totalToday + 1,
            normal:      prev.normal + (isNP || isSS ? 0 : 1),
            noPlate:     prev.noPlate + (isNP ? 1 : 0),
            suspicious:  prev.suspicious + (isSS ? 1 : 0),
          };
        });

        // Remove "isNew" highlight after 6 seconds
        setTimeout(() => {
          setAlerts(prev =>
            prev.map(a => a.id === newAlert.id ? { ...a, isNew: false } : a)
          );
        }, 6000);

        scheduleNext(); // schedule next run
      }, delay);
    };

    scheduleNext();
    return () => clearTimeout(simulationRef.current);
  }, [isRunning]);

  // ── Derived values ────────────────────────────────────────
  const newAlertCount = alerts.filter(a => a.isNew).length;
  const unreviewed    = alerts.filter(a => a.status === 'unreviewed').length;

  return (
    <div className="dashboard-root">
      <Navbar
        isRunning={isRunning}
        alertCount={unreviewed}
        newCount={newAlertCount}
      />

      <main className="main-content">
        {/* ── Stats row (spans full width) ── */}
        <div className="stats-row">
          <StatsCard
            label="Total Kendaraan"
            sublabel="Hari ini"
            value={stats.totalToday}
            color="blue"
            accentColor="var(--accent)"
            icon="🚗"
          />
          <StatsCard
            label="Kendaraan Normal"
            sublabel="Terverifikasi"
            value={stats.normal}
            color="green"
            accentColor="var(--green)"
            icon="✅"
          />
          <StatsCard
            label="Tanpa Plat Nomor"
            sublabel="Plat hilang / tertutup"
            value={stats.noPlate}
            color="orange"
            accentColor="var(--orange)"
            icon="🚫"
          />
          <StatsCard
            label="Kendaraan Mencurigakan"
            sublabel="Perlu tindakan"
            value={stats.suspicious}
            color="red"
            accentColor="var(--red)"
            icon="⚠️"
          />
        </div>

        {/* ── Left column ── */}
        <div className="left-col">
          <ScreenDetector
            isRunning={isRunning}
            onStart={handleStart}
            onStop={handleStop}
          />
          <LiveMonitor
            isRunning={isRunning}
            stream={stream}
          />
        </div>

        {/* ── Right column ── */}
        <div className="right-col">
          <AlertPanel alerts={alerts} />
        </div>
      </main>
    </div>
  );
}
